    border-bottom: 2px solid var(--color-accent);
    background-color: transparent;
    color: var(--color-accent);
  }
}

/* ==========================================================================
   PASO 8 — Secciones de Contenido (layout base)
   ========================================================================== */

.section-home,
.section-stories,
.section-news,
.section-faq {
  padding-block: var(--spacing-xl);
}

/* Hero de Home */
.section-home__hero {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
  border-radius: var(--border-radius);
  margin-bottom: var(--spacing-xl);
}

.section-home__hero h1 {
  font-size: var(--font-size-xl);
  color: var(--color-text-inverse);
  margin-bottom: var(--spacing-md);
}

@media (min-width: 768px) {
  .section-home__hero h1 {
    font-size: var(--font-size-2xl);
  }
}

.section-home__lead {
  font-size: var(--font-size-lg);
  color: var(--color-text-inverse);
  margin-bottom: var(--spacing-lg);
  max-width: 60ch;
  margin-inline: auto;
  margin-bottom: var(--spacing-lg);
}

/* Sección destacada de Home */
.section-home__featured {
  margin-top: var(--spacing-xl);
}

.section-home__featured h2 {
  font-size: var(--font-size-xl);
  margin-bottom: var(--spacing-lg);
}

/* Intro de sección */
.section-intro {
  margin-bottom: var(--spacing-xl);
}

.section-intro h2 {
  font-size: var(--font-size-xl);
  margin-bottom: var(--spacing-sm);
}

.section-intro p {
  font-size: var(--font-size-base);
  color: var(--color-text);
  max-width: 70ch;
}

/* ==========================================================================
   PASO 9 — Grid de Cards (.cards-grid)
   ========================================================================== */

.cards-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-lg);
}

@media (min-width: 600px) {
  .cards-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .cards-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ==========================================================================
   PASO 10 — Cards (.card)
   ========================================================================== */

.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition-speed) ease,
              transform var(--transition-speed) ease;
}

.card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background-color: var(--color-border);
}

.card__body {
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: var(--spacing-sm);
}

.card__title {
  font-size: var(--font-size-lg);
  font-family: var(--font-heading);
  color: var(--color-primary);
  line-height: var(--line-height-heading);
}

.card__meta {
  font-size: var(--font-size-sm);
  color: var(--color-text);
  opacity: 0.7;
}

.card__excerpt {
  font-size: var(--font-size-base);
  color: var(--color-text);
  line-height: var(--line-height-body);
  flex: 1;
}

.card__link {
  align-self: flex-start;
  margin-top: var(--spacing-sm);
  font-weight: 600;
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  text-decoration: underline;
}

.card__link:hover,
.card__link:focus {
  text-decoration: none;
  color: var(--color-primary);
}

/* ==========================================================================
   PASO 11 — FAQ (.faq)
   ========================================================================== */

.faq {
  max-width: 800px;
  margin-inline: auto;
}

.faq__list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.faq__item {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  overflow: hidden;
  transition: border-color var(--transition-speed) ease;
}

.faq__item.is-open {
  border-color: var(--color-accent);
}

.faq__question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--spacing-md);
  background: transparent;
  border: none;
  cursor: pointer;
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-primary);
  text-align: left;
  gap: var(--spacing-sm);
  transition: background-color var(--transition-speed) ease,
              color var(--transition-speed) ease;
}

.faq__question:hover,
.faq__question:focus {
  background-color: var(--color-bg);
  color: var(--color-accent);
  outline: 2px solid var(--color-accent);
  outline-offset: -2px;
}

.faq__item.is-open .faq__question {
  color: var(--color-accent);
  background-color: var(--color-bg);
}

.faq__icon {
  flex-shrink: 0;
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-accent);
  transition: transform var(--transition-speed) ease;
  line-height: 1;
  user-select: none;
}

.faq__item.is-open .faq__icon {
  transform: rotate(45deg);
}

.faq__answer {
  padding: 0 var(--spacing-md);
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-speed) ease,
              padding var(--transition-speed) ease;
}

.faq__item.is-open .faq__answer {
  max-height: 600px;
  padding: 0 var(--spacing-md) var(--spacing-md);
}

.faq__answer p {
  font-size: var(--font-size-base);
  color: var(--color-text);
  line-height: var(--line-height-body);
}

/* ==========================================================================
   PASO 12 — Footer (.site-footer)
   ========================================================================== */

.site-footer {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  padding-block: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.site-footer__content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .site-footer__content {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
    align-items: center;
  }
}

.site-footer__copy {
  font-size: var(--font-size-sm);
  color: var(--color-text-inverse);
  opacity: 0.8;
}

.site-footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
  justify-content: center;
}

@media (min-width: 768px) {
  .site-footer__links {
    justify-content: flex-end;
  }
}

.site-footer__link {
  font-size: var(--font-size-sm);
  color: var(--color-text-inverse);
  text-decoration: underline;
  opacity: 0.8;
  transition: opacity var(--transition-speed) ease,
              color var(--transition-speed) ease;
}

.site-footer__link:hover,
.site-footer__link:focus {
  color: var(--color-accent);
  opacity: 1;
  text-decoration: none;
}

/* ==========================================================================
   PASO 13 — Cookie Banner (.cookie-banner)
   ========================================================================== */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  padding: var(--spacing-md);
  border-top: 3px solid var(--color-accent);
  box-shadow: 0 -4px 16px rgba(0, 0, 0, 0.2);
}

.cookie-banner__text {
  font-size: var(--font-size-sm);
  color: var(--color-text-inverse);
  margin-bottom: var(--spacing-md);
  max-width: 80ch;
  line-height: var(--line-height-body);
}

.cookie-banner__text a {
  color: var(--color-accent);
}

.cookie-banner__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
  align-items: center;
}

.cookie-banner__btn-accept {
  background-color: var(--color-accent);
  color: var(--color-text-inverse);
  border: 2px solid var(--color-accent);
  padding: var(--spacing-sm) var(--spacing-lg);
  border-radius: var(--border-radius);
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-speed) ease,
              border-color var(--transition-speed) ease;
}

.cookie-banner__btn-accept:hover,
.cookie-banner__btn-accept:focus {
  background-color: var(--color-surface);
  color: var(--color-accent);
  border-color: var(--color-surface);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.cookie-banner__btn-reject {
  background-color: transparent;
  color: var(--color-text-inverse);
  border: 2px solid var(--color-text-inverse);
  padding: var(--spacing-sm) var(--spacing-lg);
  border-radius: var(--border-radius);
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-speed) ease,
              color var(--transition-speed) ease,
              border-color var(--transition-speed) ease;
}

.cookie-banner__btn-reject:hover,
.cookie-banner__btn-reject:focus {
  background-color: var(--color-surface);
  color: var(--color-primary);
  border-color: var(--color-surface);
  outline: 2px solid var(--color-text-inverse);
  outline-offset: 2px;
}

@media (min-width: 768px) {
  .cookie-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
    padding: var(--spacing-md) var(--spacing-lg);
  }

  .cookie-banner__text {
    margin-bottom: 0;
    flex: 1;
  }

  .cookie-banner__actions {
    flex-shrink: 0;
  }
}

/* ==========================================================================
   PASO 14 — Main Content (área principal)
   ========================================================================== */

#main-content {
  min-height: calc(100vh - var(--header-height));
  padding-top: var(--spacing-md);
}
